namespace ghidra.app.plugin.core.label;

using static org.junit.Assert;

using org.junit;

using docking;
using ghidra.app.events;
using ghidra.app.plugin.core.codebrowser;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.test;

public class OperandLabelDialogTest : AbstractGhidraHeadedIntegrationTest {
	private TestEnv env;
	private PluginTool tool;
	private LabelMgrPlugin plugin;
	private CodeBrowserPlugin cb;
	private Program program;
	private SetOperandLabelAction setLabelAction;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();

		ClassicSampleX86ProgramBuilder builder = new ClassicSampleX86ProgramBuilder();
		program = builder.getProgram();
		tool = env.launchDefaultTool(program);
		plugin = getPlugin(tool, typeof(LabelMgrPlugin));
		cb = getPlugin(tool, typeof(CodeBrowserPlugin));

		setLabelAction = (SetOperandLabelAction) getAction(plugin, "Set Operand Label");
	}

	/* @After */
	public void tearDown()
    {
		env.dispose();
	}

	private Address addr(long addr) {
		AddressSpace space = program.getAddressFactory().getDefaultAddressSpace();
		return space.getAddress(addr);
	}

	/* @Test */
	public void testSet()
    {
		OperandFieldLocation loc =
			new OperandFieldLocation(program, addr(0x100644f), null, addr(0x1001160), null, 0, 0);
		tool.firePluginEvent(
			new ProgramLocationPluginEvent(testName.getMethodName(), loc, program));
		waitForSwing();

		ActionContext context = runSwing(() => cb.getProvider().getActionContext(null));
		performAction(setLabelAction, context, false);
		waitForSwing();

		SymbolChooserDialog dialog = waitForDialogComponent(typeof(SymbolChooserDialog));

		setSelectedItem(dialog, "bob");

		pressButtonByText(dialog, "OK");
		waitForSwing();

		Symbol[] symbols = program.getSymbolTable().getSymbols(addr(0x1001160));
		assertEquals(2, symbols.length);

		cb.updateNow();
		assertEquals("dword ptr [bob]", cb.getCurrentFieldText());

		performAction(setLabelAction, context, false);
		waitForSwing();

		dialog = waitForDialogComponent(typeof(SymbolChooserDialog));

		setSelectedItem(dialog, "b");
		pressButtonByText(dialog, "OK");

		program.flushEvents();

		waitForSwing();

		symbols = program.getSymbolTable().getSymbols(addr(0x1001160));
		assertEquals(3, symbols.length);

		cb.updateNow();
		assertEquals("dword ptr [b]", cb.getCurrentFieldText());
	}

	private void setSelectedItem(SymbolChooserDialog dialog, string item) {
		runSwing(() => dialog.setSelectedItem(item));
	}
}
